function aseman_icon($name, $size = 24, $attrs = '') {
 $i = aseman_icons();
 if (!isset($i[$name])) return '';
 return '<svg ' . $attrs . ' xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="' . (int)$size . '" height="' . (int)$size . '" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">' . $i[$name] . '</svg>';
}
